import {BANDS,PRESETS,defaults} from './audio-engine.js';
import {esc} from './ui-utils.js';
export function createSoundPanel(root,audio,{onChange=()=>{}}={}){
 root.className='sound-panel';
 root.innerHTML=`<div class="sound-section"><div class="sound-title"><label for="sound-crossfade">Transição entre músicas</label><output id="crossfade-value" for="sound-crossfade"></output></div><input type="range" id="sound-crossfade" min="0" max="12" step="1" aria-describedby="crossfade-help"><div class="range-labels"><span>Desligada</span><span>12 segundos</span></div><p id="crossfade-help">Mistura o final da faixa com o começo da próxima. Não se aplica ao modo de repetir uma faixa.</p></div><div class="sound-section"><div class="sound-title"><label class="sound-enable"><input type="checkbox" id="sound-enabled"><span>Equalizador e efeitos</span></label><span class="sound-badge" id="sound-mode">Original</span></div><p id="sound-unavailable" role="status" hidden>Seu navegador não oferece suporte aos efeitos de áudio. A reprodução original continua disponível.</p><fieldset id="sound-controls"><legend class="sr-only">Personalizar o som</legend><label class="preset-label" for="sound-preset">Perfil de som</label><select id="sound-preset">${Object.entries(PRESETS).map(([id,p])=>`<option value="${id}">${esc(p.name)}</option>`).join('')}<option value="custom">Personalizado</option></select><div class="eq-bands">${BANDS.map((hz,i)=>`<label class="eq-band" for="eq-${i}"><span>${hz>=1000?hz/1000+' kHz':hz+' Hz'}<output id="eq-value-${i}" for="eq-${i}">0 dB</output></span><input id="eq-${i}" data-band="${i}" type="range" min="-12" max="12" step=".5" value="0"></label>`).join('')}</div><div class="enhance-controls"><label for="sound-bass"><span>Reforço de graves<output id="bass-value" for="sound-bass"></output></span><input id="sound-bass" type="range" min="0" max="6" step=".5"></label><label for="sound-clarity"><span>Clareza<output id="clarity-value" for="sound-clarity"></output></span><input id="sound-clarity" type="range" min="0" max="6" step=".5"></label></div><label class="sound-enable peak-toggle"><input type="checkbox" id="sound-peaks"><span>Suavizar picos de volume</span></label></fieldset><button class="text-button sound-reset" id="sound-reset" type="button">Restaurar som original</button><p class="sound-footnote">Ajustes salvos neste navegador. Os efeitos mudam a reprodução, sem alterar o arquivo ou o download. Ao reforçar frequências, o volume pode diminuir para evitar saturação.</p></div>`;
 const $=id=>root.querySelector('#'+id),db=v=>(v>0?'+':'')+String(v).replace('.',',')+' dB';
 function sync(){const s=audio.settings;$('sound-crossfade').value=s.crossfade;$('crossfade-value').textContent=s.crossfade?s.crossfade+' s':'Desligada';$('sound-enabled').checked=s.enabled;$('sound-controls').disabled=!s.enabled||!audio.supported;$('sound-unavailable').hidden=audio.supported;$('sound-enabled').disabled=!audio.supported;$('sound-crossfade').disabled=!audio.supported;$('sound-preset').value=s.preset;$('sound-mode').textContent=s.enabled?'Ligado':'Original';BANDS.forEach((_,i)=>{$('eq-'+i).value=s.bands[i];$('eq-value-'+i).textContent=db(s.bands[i]);$('eq-'+i).setAttribute('aria-valuetext',db(s.bands[i]));});for(const name of ['bass','clarity']){$('sound-'+name).value=s[name];$(name+'-value').textContent=db(s[name]);}$('sound-peaks').checked=s.peaks;}
 async function update(patch){await audio.configure(patch);sync();onChange();}
 $('sound-crossfade').addEventListener('input',e=>update({crossfade:Number(e.target.value)}));
 $('sound-enabled').addEventListener('change',e=>update({enabled:e.target.checked}));
 $('sound-preset').addEventListener('change',e=>{const preset=PRESETS[e.target.value];if(preset)update({preset:e.target.value,bands:[...preset.bands],bass:0,clarity:0});});
 root.querySelectorAll('[data-band]').forEach(input=>input.addEventListener('input',()=>{const bands=audio.settings.bands;bands[Number(input.dataset.band)]=Number(input.value);update({bands,preset:'custom'});}));
 for(const name of ['bass','clarity'])$('sound-'+name).addEventListener('input',e=>update({[name]:Number(e.target.value)}));
 $('sound-peaks').addEventListener('change',e=>update({peaks:e.target.checked}));
 $('sound-reset').onclick=()=>update({...defaults(),crossfade:audio.settings.crossfade});
 audio.addEventListener('soundchange',sync);sync();return {sync};
}
